#!/usr/bin/env bash
# Build ksud (KernelSU userspace daemon) from the vendored source in
# third-party/kernelsu, for aarch64-linux-android (NDK r29, API 26),
# and stage it under third-party/kernelsu/out/ — OUTSIDE the app package,
# so it NEVER lands in the APK or overwrites the prebuilt ksud binaries
# in android/app/src/main/assets/embed/samtimer/.
# (ksud-331-src is unreferenced by the run path and its wiring is deferred
# pending Samsung kernel source for the .ko, so it stays out of the package;
# rebuild any time with this script.)
#
#   ./third-party/kernelsu/build-ksud.sh
#
# Output: third-party/kernelsu/out/ksud-331-src
#   (a copy is also left at third-party/kernelsu/target/aarch64-linux-android/release/ksud)
# ksuinit is built first (upstream ksuinit.yml RUSTFLAGS) and copied into
# userspace/ksud/bin/aarch64/ so ksud embeds it; see the ksuinit step below.
#
# Version pin: the vendored tree is a plain copy without .git, so upstream's
# build.rs (git rev-list / git describe) would degrade to 0.0.0. This script
# injects the pinned tag via KSU_VERSION_CODE / KSU_VERSION_NAME (see
# userspace/ksud/build.rs, "TokiFontsPro vendor patch"):
#   KSU_VERSION_CODE=32680  (= 30000 + 2680 commits, v3.3.1)
#   KSU_VERSION_NAME=3.3.1
# The script then verifies the built binary actually reports
# "3.3.1 (uapi: 5)" and fails loudly if it does not.
#
# Toolchain: Rust stable (>= 1.85, edition 2024) + Android NDK r29.
# NDK is located via ANDROID_NDK_HOME, else $ANDROID_HOME/ndk/29.0.13113456,
# else ~/workspace/tools/android-sdk/ndk/29.0.13113456 (this VM's layout).
# Set CARGO_OFFLINE=1 to build with --offline (requires a warm cargo cache
# or a prior `cargo vendor` run); by default the build may fetch crates
# (crates.io + the git deps pinned in Cargo.lock) from the network.
set -euo pipefail
cd "$(dirname "$0")"

# --- locate NDK r29 -------------------------------------------------------
if [ -n "${ANDROID_NDK_HOME:-}" ] && [ -d "$ANDROID_NDK_HOME" ]; then
    NDK="$ANDROID_NDK_HOME"
elif [ -n "${ANDROID_HOME:-}" ] && [ -d "$ANDROID_HOME/ndk/29.0.13113456" ]; then
    NDK="$ANDROID_HOME/ndk/29.0.13113456"
elif [ -d "$HOME/workspace/tools/android-sdk/ndk/29.0.13113456" ]; then
    NDK="$HOME/workspace/tools/android-sdk/ndk/29.0.13113456"
else
    echo "ERROR: NDK r29 not found. Set ANDROID_NDK_HOME (want 29.0.13113456)." >&2
    exit 1
fi
export ANDROID_NDK_HOME="$NDK"
echo "NDK: $NDK"

# --- Rust toolchain -------------------------------------------------------
if ! command -v cargo >/dev/null 2>&1; then
    if [ -f "$HOME/.cargo/env" ]; then
        # shellcheck disable=SC1091
        source "$HOME/.cargo/env"
    else
        echo "ERROR: cargo not found. Install Rust stable via rustup first." >&2
        exit 1
    fi
fi
echo "cargo: $(cargo --version) | rustc: $(rustc --version)"
rustup target list --installed 2>/dev/null | grep -qx "aarch64-linux-android" \
    || rustup target add aarch64-linux-android

# --- cross-compile env (upstream .github/scripts/setup-rust-build.sh) -----
# shellcheck disable=SC1091
source .github/scripts/setup-rust-build.sh aarch64-linux-android 26
# bindgen 0.73 needs libclang: use the NDK's copy if none is configured.
if [ -z "${LIBCLANG_PATH:-}" ] && [ -f "$NDK/toolchains/llvm/prebuilt/linux-x86_64/lib/libclang.so" ]; then
    export LIBCLANG_PATH="$NDK/toolchains/llvm/prebuilt/linux-x86_64/lib/libclang.so"
fi

# --- version pin (plain copy has no .git; see header comment) -------------
export KSU_VERSION_CODE=32680
export KSU_VERSION_NAME=3.3.1
# KSU_PACKAGE_NAME intentionally left at upstream default (me.weishu.kernelsu).
# DECIDED 2026-11-25 (execution-chain round, see docs/source-integration.md
# §5 item 4): do NOT change it. The prebuilt umh_action.sh hardcodes
# `late-load --package-name me.weishu.kernelsu`, and the prebuilt .ko inside
# ksud-32525 is bound to the official Manager identity; changing the name
# would need the .ko rebuilt against Samsung kernel source — out of scope.
# ksud-331-src is not wired into the run path anyway (it embeds no .ko).

# --- ksuinit (same cargo step, upstream ksuinit.yml RUSTFLAGS) ------------
# ksuinit is built first and copied into userspace/ksud/bin/aarch64/ BEFORE
# ksud is built, so rust-embed packs it into ksud (assets.rs names "ksuinit"
# explicitly). It is only used by boot-patch flows, never by the 98260
# late-load path — embedding it changes no runtime behaviour here, it just
# stops ksud from shipping without its companion tool. The copied file is a
# build artifact regenerated by this script on every run (same as upstream
# CI's "Prepare ksuinit" step); it is not a prebuilt blob from elsewhere.
BUILTINS="$($CLANG_PATH --print-resource-dir)/lib/linux/libclang_rt.builtins-aarch64-android.a"
test -f "$BUILTINS" || { echo "ERROR: libclang_rt builtins not found: $BUILTINS" >&2; exit 1; }
KSUINIT_RUSTFLAGS="-C target-feature=+crt-static -C link-arg=-Wl,-z,max-page-size=16384 -C link-arg=-Wno-unused-command-line-argument -C link-arg=$BUILTINS"
KSUINIT_ARGS=(build --package ksuinit --target aarch64-linux-android --release --locked)
if [ "${CARGO_OFFLINE:-0}" = "1" ]; then
    KSUINIT_ARGS+=(--offline)
fi
RUSTFLAGS="$KSUINIT_RUSTFLAGS" cargo "${KSUINIT_ARGS[@]}"
KSUINIT="target/aarch64-linux-android/release/ksuinit"
[ -f "$KSUINIT" ] || { echo "ERROR: $KSUINIT not produced" >&2; exit 1; }
cp "$KSUINIT" userspace/ksud/bin/aarch64/ksuinit
echo "ksuinit staged into userspace/ksud/bin/aarch64/ksuinit ($(stat -c %s "$KSUINIT") B)"

CARGO_ARGS=(build --target aarch64-linux-android --release --locked
    --manifest-path ./userspace/ksud/Cargo.toml)
if [ "${CARGO_OFFLINE:-0}" = "1" ]; then
    CARGO_ARGS+=(--offline)
fi
cargo "${CARGO_ARGS[@]}"

KSUD="target/aarch64-linux-android/release/ksud"
[ -f "$KSUD" ] || { echo "ERROR: $KSUD not produced" >&2; exit 1; }

# --- verify the version string before staging -----------------------------
# The binary is aarch64 Android and cannot be executed on this x86_64 host,
# so verify via strings: FULL_VERSION is "3.3.1 (uapi: 5)".
# NOTE: strings output goes to a temp file first — piping straight into
# `grep -q` under `set -o pipefail` is racy: grep exits on first match,
# strings then dies on SIGPIPE (exit 141) and the check spuriously fails.
STRINGS_TMP="$(mktemp)"
trap 'rm -f "$STRINGS_TMP"' EXIT
strings "$KSUD" > "$STRINGS_TMP"
if ! grep -Fq "3.3.1 (uapi: 5)" "$STRINGS_TMP"; then
    echo "ERROR: built ksud does not contain '3.3.1 (uapi: 5)'" >&2
    grep -F "uapi:" "$STRINGS_TMP" | head -5 >&2 || true
    exit 1
fi
if ! grep -Fq "32680" "$STRINGS_TMP"; then
    echo "ERROR: built ksud does not contain VERSION_CODE 32680" >&2
    exit 1
fi
# ksuinit must be embedded (its vermagic-replacement string is distinctive).
if ! grep -Fq "Cannot replace module vermagic" "$STRINGS_TMP"; then
    echo "ERROR: built ksud does not embed ksuinit" >&2
    exit 1
fi
echo "Version check OK: 3.3.1 (uapi: 5), VERSION_CODE 32680, ksuinit embedded"

# --- stage outside the app package (never into assets) ------------------
DEST="out/ksud-331-src"
mkdir -p "$(dirname "$DEST")"
cp "$KSUD" "$DEST"
ls -lh "$DEST"
sha256sum "$DEST"
echo "Staged: $DEST (outside the app package; prebuilt ksud-32525 / ksud-32601 / ksud-331-kdp untouched)"
